      },
      {
        "component_id": "comp_drain_hose",
        "name": "Drain hose",
        "description": "Hose connected to the bottom of the filter bowl and exiting through the base of the power supply.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Board with connector J5, from which the fan may be disconnected during leak testing.",
        "category": "electrical"
      },
      {
        "component_id": "comp_torch",
        "name": "Torch",
